card_mod.style:
/* Rendu identique sur telephone, tablette et PC : la carte ne suit plus
   la largeur de la colonne du navigateur. Combinee aux dimensions en px
   (plus aucun vh), la mise en page est la meme partout. */
ha-card {
  width: 100% !important;
  max-width: 400px !important;
  margin: 0 auto !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}

ha-card { 
  background: none !important; 
  border: none !important;
  box-shadow: none !important; 
}

card_mod.style:
/* Personnalisation des points de pagination */ /* Le bandeau de pagination est un calque plein largeur en z-index 10 :
   sans ceci il absorbe les clics des elements situes en bas de carte. */
.swiper-pagination {
  pointer-events: none !important;
} .swiper-pagination-bullet {
  background: #000000 !important;
  opacity: 0.7 !important;
}  .swiper-pagination-bullet-active {
  background: #FFFFFF !important;
  opacity: 1 !important;
}

ha-card {
  padding-top: 0px !important;
  padding-bottom: 30px !important;
  border: 2px solid #808080;
  height: 350px !important; 
  background-image: url("/local/images/dark-texture.png") !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  position: relative; /* Important pour le positionnement */
}

