  white-space: normal !important;
  font-size: 10px !important;
  line-height: 1.1 !important;
  word-break: break-word !important;
}
ha-tile-info { overflow: visible !important; }
ha-card .container .content.vertical {
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  height: 44px !important;
  min-height: 44px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  --row-height: 0px;
}

ha-card { background: none !important; border: none !important; box-shadow: none !important; }
ha-tile-info { display: none !important; }
ha-tile-icon {
  box-sizing: border-box !important;
  width: 40px !important;
  height: 40px !important;
}
ha-card {
  margin-top: 3px !important;
  margin-bottom: 4px !important;
  margin-left: auto !important;
  margin-right: auto !important;
}
ha-card .container .content.vertical {
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  min-height: 0 !important;
  --row-height: 0px;
}

cards.primary:
{%- set all_events = state_attr('sensor.temps_calendrier_hindou', 'events') or [] -%}{%- set matches = all_events | selectattr('summary', 'search', "Diwali") | list -%}{%- set today = now().strftime('%Y-%m-%d') -%}{%- set future = matches | selectattr('start', 'ge', today) | list -%}{%- set event = (future | sort(attribute='start'))[0] if future | count > 0 else ((matches | sort(attribute='start'))[-1] if matches | count > 0 else None) -%}{%- set mois_fr = {1:'janvier',2:'février',3:'mars',4:'avril',5:'mai',6:'juin',7:'juillet',8:'août',9:'septembre',10:'octobre',11:'novembre',12:'décembre'} -%}{%- set d = strptime(event.start, '%Y-%m-%d') if event else None -%}{{ (d.day | string) + '
' + mois_fr[d.month] + '
' + (d.year | string) if d else '' }}

